fn output(containers:&crate::game::machines::Containers<'_>,view:&crate::game::machines::View,slot:usize)->core::ops::ControlFlow<bool>{let p=view.parts[0].0;let name=containers.name(containers.world.block(p.0,p.1,p.2));if crate::game::create_runtime::machines::station(name).is_some(){core::ops::ControlFlow::Break((9..18).contains(&slot))}else if crate::game::create_runtime::machines::container_size(name)==Some(0){core::ops::ControlFlow::Break(false)}else{core::ops::ControlFlow::Continue(())}}
